input.script:
() => { 
  const elt = document.getElementById('customization');
  if (elt) {
    const rect = elt.getBoundingClientRect();
    return { 
      found: true, 
      id: elt.id,
      text: elt.textContent.substring(0, 200),
      top: rect.top,
      viewportHeight: window.innerHeight
    };
  }
  return { found: false };
}
